    k.drawImage(c, -CWd / 2, -CHd / 2, CWd, CHd);
    k.strokeStyle = 'rgba(255,255,255,.45)'; k.lineWidth = 1; rr(k, -CWd / 2 + 0.5, -CHd / 2 + 0.5, CWd - 1, CHd - 1, 10); k.stroke();
    k.restore();
    cursor(k, cx, cy, 0, C.ink);
  });
